Add({
	id = "loch-modan",
	title = "Loch Modan",
	faction = "Alliance",
	continent = "Eastern Kingdoms",
	maps = { 1432, 48 },
	zone = "Loch Modan",
	unlock = {
		{ type = "zone" },
		{ type = "map" },
