			text = [=[Hinderweir sees the pattern that others miss. First the {link:thandol-span}Thandol Span{/link} was destroyed, then {link:dun-modr}Dun Modr{/link} was pillaged. He has no doubt that the dam is the next target of the {link:dark-iron-dwarves}Dark Iron clan{/link}, and if it falls, {link:the-loch}the Loch{/link} falls with it.]=],
		},
		{
			title = "Deeds",
			text = [=[• He keeps watch over the {link:stonewrought-dam}Stonewrought Dam{/link} with a thin guard.
• He sends a sample of Dark Iron powder to the explosives expert of {link:dun-modr}Dun Modr{/link}.
• He prepares the mixture that saves the dam from a Dark Iron charge.]=],
		},
	},
	chapters = {
		{
			key = "a-clue-on-the-ramp",
			title = "A Clue on the Ramp",
			hint = [=[Search the eastern ramp of the dam for signs of the Dark Irons.]=],
			unlock = {
				{ type = "quest", id = 199 },
			},
			text = [=[Dark Iron sappers had been seen on the eastern ramp of the dam. Among their leavings was a barrel of a strange-smelling powder. Hinderweir judged it an explosive of some kind, and he sent a sample north through the Algaz Gate to {link:ashlan-stonesmirk}Ashlan Stonesmirk{/link}, the powder master of the regiment at {link:dun-modr}Dun Modr{/link}, with orders to keep to the roads.]=],
		},
		{
			key = "seaforium",
			title = "Seaforium",
			hint = "Learn what the Dark Iron powder truly is.",
			unlock = {
				{ type = "quest", id = 274 },
			},
			text = [=[Stonesmirk knew the powder by its silver crystals and its smell: seaforium. Dry, it was harmless. Wet, it could tear a mountain apart. He sent back a disarming colloid, and word of what else was needed: the venom of the lurker spiders of the hills, the tear of a crocolisk and a rare crystal of the kind the {link:mo-grosh-ogres}Mo'grosh ogres{/link} mine.]=],
		},
		{
			key = "beneath-the-dam",
			title = "Beneath the Dam",
			hint = "Save the Stonewrought Dam.",
			unlock = {
				{ type = "quest", id = 283 },
			},
			text = [=[Before the mixture was ready, Hinderweir saw Dark Iron insurgents swimming toward the dam with a great keg, and no mountaineer on hand to stop them. The charge lay at the foot of the dam, under the water, and the mixture was stirred into it in time. The dam was saved. Hinderweir did not pretend that it was saved for good.]=],
