	sections = {
		{
			title = "Summary",
			text = [=[Prospector Darteus Ironband leads the {link:explorers-league}Explorers' League{/link} dig among the ancient ruins south-east of {link:the-loch}the Loch{/link}. He is stout and honest, and he values results. Lately he has had few. The {link:stonesplinter-troggs}Stonesplinter troggs{/link} have overrun his site, his blastpowder never arrives, and one of his fellow prospectors in the south has fallen silent.]=],
		},
		{
			title = "Significance",
			text = [=[Ironband is a scholar in the field. He believes that the carved idols of his dig may reveal a link between the troggs and the titans, and he chases that question from {link:loch-modan}Loch Modan{/link} to the {link:badlands}Badlands{/link}. What he learns reaches the League in {link:ironforge}Ironforge{/link}.]=],
		},
		{
			title = "Deeds",
			text = [=[• He leads the excavation and writes its reports for the League.
