			hint = "Carry the prospector's report to Thelsamar.",
			unlock = {
				{ type = "quest", id = 298 },
			},
			text = [=[Ironband's report is short and patient. The dig goes on, slowed by troggs more aggressive than usual. Most finds are interesting and no more. One is not: the carved idols draw the troggs to them, and drive some of them berserk. More study is needed. And, once more, where is his blastpowder?]=],
