			hint = "Learn what befell Prospector Agmond in the Badlands.",
			unlock = {
				{ type = "quest", id = 739 },
			},
			text = [=[Agmond's body was found in the {link:badlands}Badlands{/link}, broken and picked clean, with a single word scratched into the sandstone by his hand: {link:murdaloc}Murdaloc{/link}. Ironband mourned him as a fighter with a thick skull and a hard swing. He feared that the urns Agmond's diggers found had roused the troggs, just as his own idols had.]=],
