			title = "Summary",
			text = [=[Magistrate Bluntnose governs {link:thelsamar}Thelsamar{/link}, and he is losing patience with {link:ironforge}Ironforge{/link}. It took two months to hear that the town would be spared a few soldiers, and he has been told it will be two more before they arrive. Meanwhile Thelsamar, the excavation and the dam stand open to attack.]=],
		},
		{
			title = "Significance",
			text = [=[Bluntnose is the voice of {link:the-loch}the Loch{/link}'s common folk. Where the captains ask for soldiers who never come, the magistrate reaches into the town's purse and hires whoever will fight. Through him, the defense of {link:loch-modan}Loch Modan{/link} passes into the hands of strangers.]=],
		},
		{
			title = "Deeds",
			text = [=[• He hires sell-swords against the {link:mo-grosh-ogres}Mo'grosh ogres{/link} of the north-east.
• He puts a price on the head of {link:chok-sul}Chok'sul{/link}, the {link:ogres}ogre{/link} he believes leads the attacks on his town.
• He means to turn on the troggs once the ogres are dealt with.]=],
		},
		{
			title = "Unrecorded",
			text = [=[Little is written of Bluntnose's life before his office. This entry records only what his town and his orders reveal.]=],
		},
	},
	chapters = {
