			key = "hired-arms",
			title = "Hired Arms",
			hint = [=[Take the magistrate's coin and fight the ogres of the north-east.]=],
			unlock = {
				{ type = "quest", id = 255 },
			},
			text = [=[The ogres had set up camp on the north-eastern shore of the lake, and there was no one to send against them. So Bluntnose sent strangers. When they came back with word of ogres slain, he was delighted. With the ogres in hand, he said, the town could at last turn on the troggs.]=],
		},
		{
			key = "the-head-of-chok-sul",
			title = "The Head of Chok'sul",
			hint = "Answer the wanted poster that hangs in Thelsamar.",
			unlock = {
				{ type = "quest", id = 256 },
			},
			text = [=[In {link:thelsamar}Thelsamar{/link} hangs a notice under the magistrate's seal. It names {link:chok-sul}Chok'sul{/link}, the {link:ogres}ogre{/link} thought to lead and plan the raids on the town, the dam and the dig, and it promises coin for proof of his death. When that proof was laid before him, Bluntnose recoiled at the sight, and then paid gladly.]=],
