Add({
	kind = "topic",
	id = "stonesplinter-troggs",
	title = "Stonesplinter Troggs",
	aliases = { "Stonesplinter", "Stonesplinter troggs", "Stonesplinter tribe" },
	category = "group",
	region = "loch-modan",
	unlock = {
		{ type = "read" },
		{ type = "quest", id = 224 },
	},
	sections = {
		{
			title = "Summary",
			text = [=[The Stonesplinter are the {link:troggs}troggs{/link} of {link:loch-modan}Loch Modan{/link}. They take their name from {link:stonesplinter-valley}Stonesplinter Valley{/link} in the south-west, and they are the greatest danger {link:the-loch}the Loch{/link} faces. No chronicle records when they first came up from the deep places here.]=],
		},
		{
			title = "Their Lands",
			text = [=[They hold {link:stonesplinter-valley}Stonesplinter Valley{/link} and the southern hills, where their chieftain {link:grawmug}Grawmug{/link} keeps the deepest cave. They have taken the largest island of {link:the-loch}the Loch{/link}. At {link:ironband-s-excavation-site}Ironband's Excavation Site{/link}, where they surfaced among the ruins, a chieftain called Galgosh and a tribal shaman called Magosh rule the diggings. Their ranks hold scouts, skullthumpers and bonesnappers, and seers, shamans and geomancers who work a crude magic of the earth.]=],
		},
		{
			title = "In the Present Day",
			text = [=[The Stonesplinter are drawn to the carved idols of the excavation, and some of them are driven berserk by the idols. {link:prospector-ironband}Prospector Ironband{/link} hopes that the idols will one day explain the bond between the troggs and the titans. Until then, the mountaineers of the southern tower fight them with what little they have. They count the troggs they kill by their stone teeth.]=],
		},
	},
})

Add({
	kind = "topic",
	id = "mo-grosh-ogres",
	title = "Mo'grosh Ogres",
	aliases = { "Mo'grosh", "Mo'grosh ogres", "Mo'grosh clan" },
	category = "group",
	region = "loch-modan",
	unlock = {
		{ type = "read" },
		{ type = "quest", id = 255 },
	},
	sections = {
		{
			title = "Summary",
			text = [=[The Mo'grosh are a clan of {link:ogres}ogres{/link} who have made their home in the caves of the {link:mo-grosh-stronghold}Mo'grosh Stronghold{/link}, in the north-east of {link:loch-modan}Loch Modan{/link}. No chronicle records where they came from or when they settled there.]=],
		},
		{
			title = "Their Ways",
			text = [=[They are brutes, enforcers and shamans, with mystics among them, and they follow a chieftain called {link:chok-sul}Chok'sul{/link}. They mine crystals in their caves, rare enough that the dwarves must fight for a single one. They raid the roads of {link:the-loch}the Loch{/link}, and they are blamed for attacks on {link:thelsamar}Thelsamar{/link}, the {link:stonewrought-dam}Stonewrought Dam{/link} and the excavation. They once ambushed an ore caravan bound for Thelsamar from the {link:wetlands}Wetlands{/link} and carried the ore off to their camp.]=],
		},
		{
			title = "In the Present Day",
			text = [=[The Magistrate of {link:thelsamar}Thelsamar{/link} has hired sell-swords to break them, and a price hangs over the head of {link:chok-sul}Chok'sul{/link}. The magistrate wants the ogres dealt with first, so that the town can at last turn on the troggs.]=],
		},
	},
})

